UPDATE generation_task SET state = #{state}, state_note = #{note}
WHERE id = #{taskId} AND state IN

  #{allowed}

UPDATE generation_task SET state = #{state}, state_note = #{note}
WHERE id = #{taskId}
  AND state NOT IN ('RESULT_PENDING','FAILED_PENDING_FOLLOWUP',
    'CANCELLED_PENDING_FOLLOWUP','QUEUE_TIMEOUT','SUCCEEDED','FAILED','CANCELLED')

UPDATE generation_task SET state = 'REVIEW', state_note = #{note}
WHERE id = #{taskId} AND accounting_state = 'FROZEN'
  AND state IN ('RESULT_PENDING','REVIEW')

UPDATE generation_task
SET state = #{state}, state_note = #{note}
WHERE id = #{taskId} AND state = 'CANCEL_REQUESTED' AND accounting_state = 'FROZEN'

